/**
 * Reference ↔ animation comparison (research tool): the reference capture of a
 * step next to the rendered clip / 2D / 3D frame at the same moment. Reference captures are local
 * only (public/_refs, git-ignored, never bundled); without them the page says so.
 */
import { useEffect, useState } from 'preact/hooks';
import { useApp } from '../../data/store';
import { exerciseById } from '../../rehab/exercises';
import { planFor, programFor } from '../../rehab/motion';
import { clipFor } from '../../rehab/demoClips';
import { mmss } from '../../rehab/stretches';
import { AppBar, Segmented } from '../components/common';
import { RehabStage, holdTime, useExerciseClock } from '../rehab/stage';

interface RefStep {
  exercise: string;
  step: number;
  /** Captures in public/_refs/<dir>/ with their video time. */
  dir: string;
  shots: { file: string; at: string; note: string }[];
}

const REFS: RefStep[] = [
  {
    exercise: 'frontalis-lift',
    step: 0,
    dir: '01-frontalis',
    shots: [
      { file: '01.png', at: '1:12', note: '머리끝 고정 + 이마 손바닥' },
      { file: '03.png', at: '1:19', note: '눈썹 쪽으로 밀어 내린 끝' },
      { file: '04.png', at: '1:30', note: '여러 각도' },
    ],
  },
  {
    exercise: 'brow-relax',
    step: 0,
    dir: '02-brow',
    shots: [
      { file: '01.png', at: '1:48', note: '준비' },
      { file: '03.png', at: '1:55', note: '눈썹 안쪽 고정 + 위 대각선' },
      { file: '05.png', at: '2:05', note: '여러 각도' },
    ],
  },
  {
    exercise: 'eye-open',
    step: 0,
    dir: '03-orb1',
    shots: [
      { file: '02.png', at: '2:26', note: '눈 안쪽 고정' },
      { file: '07.png', at: '2:37', note: '양손 시작 (안쪽)' },
      { file: '09.png', at: '2:43', note: '바깥쪽으로 민 끝' },
    ],
  },
  {
    exercise: 'eye-open',
    step: 1,
    dir: '04-orb2',
    shots: [
      { file: '02.png', at: '3:18', note: '손바닥으로 눈꼬리 바깥' },
      { file: '04.png', at: '3:31', note: '손바닥으로 바깥쪽 (근접)' },
      { file: '05.png', at: '3:36', note: '여러 각도' },
    ],
  },
  {
    exercise: 'orbicularis-sweep',
    step: 0,
    dir: '05-orb3',
    shots: [
      { file: '04.png', at: '4:10', note: '눈썹 밑 위로 · 눈 아래 아래로' },
      { file: '06.png', at: '4:31', note: '근접' },
    ],
  },
  {
    exercise: 'orbicularis-sweep',
    step: 1,
    dir: '06-orb5',
    shots: [
      { file: '01.png', at: '4:37', note: '눈 바깥 위아래' },
      { file: '04.png', at: '4:44', note: '근접' },
    ],
  },
  {
    exercise: 'levator-labii',
    step: 0,
    dir: '07-nasi',
    shots: [
      { file: '01.png', at: '5:17', note: '엄지로 눈과 코 사이 고정' },
      { file: '04.png', at: '5:25', note: '코 옆 수직 아래' },
      { file: '08.png', at: '5:37', note: '근접' },
    ],
  },
  { exercise: 'levator-labii', step: 1, dir: '07-nasi', shots: [{ file: '09.png', at: '5:42', note: '입안 손가락 변형' }] },
  {
    exercise: 'levator-superioris',
    step: 0,
    dir: '08-labii',
    shots: [
      { file: '02.png', at: '6:14', note: '눈 아래 안쪽 고정' },
      { file: '06.png', at: '6:35', note: '고개 위 대각선' },
      { file: '08.png', at: '6:31', note: '근접' },
      { file: '10.png', at: '7:04', note: '근접 (입안 엄지)' },
    ],
  },
];

export function PoseLab() {
  const { profile } = useApp();
  const [sel, setSel] = useState(2);
  const [shot, setShot] = useState(1);
  const [mode, setMode] = useState<'2d' | '3d' | 'video'>('video');
  const [missing, setMissing] = useState(false);
  const r = REFS[sel]!;
  const ex = exerciseById(r.exercise)!;
  const plan = planFor(ex);
  const clock = useExerciseClock(plan.total);
  const program = programFor(ex.id);
  const step = program?.steps[r.step];
  const s = r.shots[Math.min(shot, r.shots.length - 1)]!;
  const hasClip = !!clipFor(ex.id, step?.id);
  const stageMode = mode === 'video' && !hasClip ? '3d' : mode;

  useEffect(() => {
    clock.seek(holdTime(plan, r.step));
    setMissing(false);
  }, [sel]);

  if (!profile) return null;
  const view = { affectedSide: profile.affectedSide, mirror: true, showMuscle: true, callouts: true, ghostHands: true, riggedHands: true };
  return (
    <>
      <AppBar title="레퍼런스 대조" sub="캡처와 같은 단계의 그림을 나란히" onBack />
      <main class="main wide">
        <div class="tabs-scroll" role="tablist">
          {REFS.map((x, i) => (
            <button
              class={`btn sm ${i === sel ? 'primary' : ''}`}
              onClick={() => {
                setSel(i);
                setShot(Math.min(1, x.shots.length - 1));
              }}
            >
              {exerciseById(x.exercise)!.title.replace(' 스트레칭', '')}
              {programFor(x.exercise)!.steps.length > 1 ? ` ${x.step + 1}` : ''}
            </button>
          ))}
        </div>
        <div class="poselab">
          <figure class="card tight">
            {missing ? (
              <p class="small muted">참고 캡처가 이 기기에 없습니다 (저작권 때문에 로컬 전용: public/_refs/{r.dir}).</p>
            ) : (
              <img src={`_refs/${r.dir}/${s.file}`} alt={`참고 캡처 ${s.at}`} onError={() => setMissing(true)} />
            )}
            <figcaption class="xsmall">
              <b>원본 {s.at}</b> · {s.note}
            </figcaption>
            <div class="row wrap" style={{ gap: '6px' }}>
              {r.shots.map((x, i) => (
                <button class={`btn sm ${i === shot ? 'primary' : ''}`} onClick={() => setShot(i)}>
                  {x.at}
                </button>
              ))}
            </div>
          </figure>
          <div class="card tight">
            <Segmented
              label="보기"
              value={stageMode}
              onChange={setMode}
              options={[
                ...(hasClip ? [{ value: 'video' as const, label: '영상' }] : []),
                { value: '3d' as const, label: '3D' },
                { value: '2d' as const, label: '2D' },
              ]}
            />
            <RehabStage ex={ex} plan={plan} clock={clock} mode={stageMode} view={view} loupe={false} />
            <input
              class="range"
              type="range"
              min={0}
              max={Math.round(plan.total * 10)}
              value={Math.round(clock.get() * 10)}
              aria-label="장면 위치"
              onInput={(e) => clock.seek(Number((e.target as HTMLInputElement).value) / 10)}
            />
            <div class="row wrap" style={{ gap: '6px' }}>
              {(['prepare', 'stretch', 'hold'] as const).map((k) => (
                <button
                  class="btn sm"
                  onClick={() => {
                    const b = plan.blocks.find((x) => x.step === r.step && x.phase.key === k)!;
                    clock.seek(b.start + b.phase.dur * (k === 'hold' ? 0.3 : 0.95));
                  }}
                >
                  {k === 'prepare' ? '손 대기' : k === 'stretch' ? '늘리는 중' : '유지'}
                </button>
              ))}
            </div>
            {step && (
              <p class="xsmall ink2">
                {step.title} · 영상 {mmss(step.videoAt)} · 좌표 {step.source === 'frame-grid' ? '격자 측정' : '영상 판독'}
              </p>
            )}
          </div>
        </div>
      </main>
    </>
  );
}
